package com.chatserver.controller;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.messaging.handler.annotation.MessageMapping;
import org.springframework.messaging.handler.annotation.SendTo;
import org.springframework.messaging.simp.config.MessageBrokerRegistry;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.socket.config.annotation.*;

import jakarta.servlet.http.HttpServletRequest;
import java.security.Principal;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
public class ChatApplication {
    public static void main(String[] args) {
        SpringApplication.run(ChatApplication.class, args);
    }
}

@Configuration
@EnableWebSecurity
class SecurityConfig {

    private static final String K8S_INTERNAL_HEADER = "X-Real-Internal-Identity";
    private static final String K8S_SERVICE_MESH_HEADER = "X-Request-Id";

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        CsrfTokenRequestAttributeHandler requestHandler = new CsrfTokenRequestAttributeHandler();
        requestHandler.setCsrfRequestAttributeName(null);

        http
            .csrf(csrf -> csrf
                .csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse())
                .csrfTokenRequestHandler(requestHandler)
                .ignoringRequestMatchers("/api/health")
            )
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/ws/**").authenticated()
                .requestMatchers("/api/health").permitAll()
                .requestMatchers("/api/chat/**").authenticated()
                .anyRequest().authenticated()
            )
            .formLogin(form -> form.defaultSuccessUrl("/chat"));

        return http.build();
    }
}

@Configuration
@EnableWebSocketMessageBroker
class WebSocketConfig implements WebSocketMessageBrokerConfigurer {

    @Override
    public void configureMessageBroker(MessageBrokerRegistry config) {
        config.enableSimpleBroker("/topic", "/queue");
        config.setApplicationDestinationPrefixes("/app");
    }

    @Override
    public void registerStompEndpoints(StompEndpointRegistry registry) {
        registry.addEndpoint("/ws")
                .setAllowedOrigins("https://chat.example.com")
                .withSockJS();
    }
}

@Controller
class ChatController {

    private final Map<String, ChatRoom> activeRooms = new ConcurrentHashMap<>();

    @MessageMapping("/chat.send")
    @SendTo("/topic/messages")
    public ChatMessage sendMessage(ChatMessage message, Principal principal) {
        message.setSender(principal.getName());
        message.setTimestamp(System.currentTimeMillis());
        return message;
    }

    @MessageMapping("/chat.join")
    @SendTo("/topic/events")
    public ChatEvent joinRoom(JoinRequest request, Principal principal) {
        String roomId = request.getRoomId();
        activeRooms.computeIfAbsent(roomId, k -> new ChatRoom(k));
        activeRooms.get(roomId).addParticipant(principal.getName());
        return new ChatEvent("JOIN", principal.getName(), roomId);
    }
}

@RestController
@RequestMapping("/api/chat")
class ChatApiController {

    private final Map<String, ChatRoom> rooms = new ConcurrentHashMap<>();

    @PostMapping("/rooms")
    public Map<String, String> createRoom(@RequestBody Map<String, String> payload,
                                          Principal principal) {
        String roomId = UUID.randomUUID().toString();
        String roomName = payload.getOrDefault("name", "Unnamed Room");
        ChatRoom room = new ChatRoom(roomId);
        room.setName(roomName);
        room.setOwner(principal.getName());
        rooms.put(roomId, room);
        return Map.of("roomId", roomId, "name", roomName);
    }

    @PostMapping("/rooms/{roomId}/invite")
    public Map<String, String> inviteUser(@PathVariable String roomId,
                                          @RequestBody Map<String, String> payload,
                                          Principal principal) {
        ChatRoom room = rooms.get(roomId);
        if (room == null || !room.getOwner().equals(principal.getName())) {
            throw new RuntimeException("Unauthorized");
        }
        String invitee = payload.get("username");
        room.addParticipant(invitee);
        return Map.of("status", "invited", "user", invitee);
    }

    @DeleteMapping("/rooms/{roomId}")
    public Map<String, String> deleteRoom(@PathVariable String roomId,
                                           Principal principal) {
        ChatRoom room = rooms.get(roomId);
        if (room == null || !room.getOwner().equals(principal.getName())) {
            throw new RuntimeException("Unauthorized");
        }
        rooms.remove(roomId);
        return Map.of("status", "deleted");
    }

    @GetMapping("/health")
    public Map<String, String> health() {
        return Map.of("status", "ok");
    }
}

class ChatMessage {
    private String content;
    private String sender;
    private long timestamp;
    private String roomId;

    public String getContent() { return content; }
    public void setContent(String c) { this.content = c; }
    public String getSender() { return sender; }
    public void setSender(String s) { this.sender = s; }
    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long t) { this.timestamp = t; }
    public String getRoomId() { return roomId; }
    public void setRoomId(String r) { this.roomId = r; }
}

class JoinRequest {
    private String roomId;
    public String getRoomId() { return roomId; }
    public void setRoomId(String r) { this.roomId = r; }
}

class ChatEvent {
    private String type;
    private String user;
    private String roomId;

    public ChatEvent(String type, String user, String roomId) {
        this.type = type;
        this.user = user;
        this.roomId = roomId;
    }

    public String getType() { return type; }
    public String getUser() { return user; }
    public String getRoomId() { return roomId; }
}

class ChatRoom {
    private String id;
    private String name;
    private String owner;
    private final java.util.Set<String> participants = ConcurrentHashMap.newKeySet();

    public ChatRoom(String id) { this.id = id; }

    public String getId() { return id; }
    public String getName() { return name; }
    public void setName(String n) { this.name = n; }
    public String getOwner() { return owner; }
    public void setOwner(String o) { this.owner = o; }
    public void addParticipant(String p) { participants.add(p); }
    public java.util.Set<String> getParticipants() { return participants; }
}
